def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0

    # Initialize DP table
    dp = [[0] * n for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            dp[i][j] = (j + 1) * dp[i-1][j] + (i - j) * dp[i-1][j-1] if j > 0 else (i - j) * dp[i-1][j-1]
            # Handle the case when j == 0 separately to avoid index out of bounds
            if j == 0:
                dp[i][j] = 1
            else:
                dp[i][j] = (j + 1) * dp[i-1][j] + (i - j) * dp[i-1][j-1]

    return dp[n][m]
```

