            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2  # Two identical characters
                else:
                    dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]
