def find_ways(n):
    if n % 2 != 0:
        return 0

    # Catalan numbers: C_k = (1/(k+1)) * binomial(2k, k)
    # For sequences of length n=2k with non-negative prefix sums using +1 and -1 steps
    k = n // 2

    # Calculate binomial coefficient (2k choose k)
    def binomial(n, r):
        if r < 0 or r > n:
            return 0
        r = min(r, n - r)
        result = 1
        for i in range(r):
            result = result * (n - i) // (i + 1)
        return result

    return binomial(2 * k, k) // (k + 1)
```

