def count_Rectangles(r):
    if r <= 0:
        return 0
    count = 0
    # Iterate over all possible top-left corners (x1, y1) and bottom-right corners (x2, y2)
    # where x1, y1, x2, y2 are integers and x1 < x2, y1 < y2
    # A rectangle is inside the circle if all four corners are inside or on the circle
    # Circle equation: x^2 + y^2 <= r^2

    # We'll consider all integer coordinates from -r to r
    coords = list(range(-r, r + 1))

    for x1 in coords:
        for y1 in coords:
            for x2 in coords:
                for y2 in coords:
                    if x1 < x2 and y1 < y2:
                        # Check if all four corners are within the circle
                        corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]
                        if all(x*x + y*y <= r*r for x, y in corners):
                            count += 1
    return count
```

