def max_profit(prices, k):
    if not prices or k == 0:
        return 0

    n = len(prices)
    # If k is large enough, we can do as many transactions as we want
    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i-1]:
                profit += prices[i] - prices[i-1]
        return profit

    # dp[i][j][0] = max profit on day i with at most j transactions and no stock held
    # dp[i][j][1] = max profit on day i with at most j transactions and stock held
    dp = [[[0, 0] for _ in range(k + 1)] for _ in range(n)]

    # Initialize first day
    for j in range(k + 1):
        dp[0][j][0] = 0
        dp[0][j][1] = -prices[0]

    for i in range(1, n):
        for j in range(k + 1):
            # No stock held: either continue without stock or sell today
