import sys
from functools import lru_cache

def main():
    MOD = 10**9 + 7
    nums = list(map(int, sys.stdin.read().split()))
    n = len(nums)

    # Precompute which pairs satisfy the divisibility condition
    # condition[i][j] = True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    condition = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    condition[i][j] = True

    # Use memoization with bitmask for dynamic programming
    # dp(mask, last) = number of ways to arrange the numbers represented by mask,
    # ending with the number at index 'last'
    @lru_cache(maxsize=None)
    def dp(mask, last):
        # If all numbers are used, we have a complete permutation
        if mask == (1 << n) - 1:
            return 1

        total = 0
        for i in range(n):
            # If the i-th number is not used yet
            if not (mask & (1 << i)):
                # Check if it can follow the last number in the sequence
                if last == -1 or condition[last][i]:
                    total = (total + dp(mask | (1 << i), i)) % MOD
        return total

    # Start with an empty mask and no last element (-1)
    result = dp(0, -1)
    dp.cache_clear()
    print(result)

