def punishment_number(n):
    def can_partition(s, target):
        # Try all possible partitions of string s into contiguous substrings
        # such that the sum of their integer values equals target
        length = len(s)

        # Use DFS with memoization
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(pos, current_sum):
            if pos == length:
                return current_sum == target

            num = 0
            for i in range(pos, length):
                num = num * 10 + int(s[i])
                # If current number exceeds target, no need to continue
                if current_sum + num > target:
                    break
                if dfs(i + 1, current_sum + num):
                    return True
            return False

        return dfs(0, 0)

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)
        if can_partition(square_str, i):
            total += square
    return total

